import{_ as s,a0 as o,w as i,s as a,ao as d,I as r,x as e,a1 as u,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧-使用OpenDNS来保护你的电脑 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-使用OpenDNS来保护你的电脑 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-使用OpenDNS来保护你的电脑 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-使用OpenDNS来保护你的电脑 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure","title":"每日Ubuntu小技巧-使用OpenDNS来保护你的电脑","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure.md","filePath":"[post].md"}'),l={name:"201312/Daily Ubuntu Tips–Protect Your Computers Using OpenDNS’ Secure DNS Infrastructure.md"};function D(m,t,S,N,f,T){const n=o("Link");return i(),a("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-使用opendns来保护你的电脑" tabindex="-1">每日Ubuntu小技巧-使用OpenDNS来保护你的电脑 <a class="header-anchor" href="#每日ubuntu小技巧-使用opendns来保护你的电脑" aria-label="Permalink to “每日Ubuntu小技巧-使用OpenDNS来保护你的电脑”">​</a></h1><p>互联网是个大熔炉。无论是好人还是坏人，都可以和我们一样连接到网络。那些制作病毒感染人们电脑的坏蛋以及寻求保护人们的好人们全都连接到同一网络中。</p><p>就像人们所说的那样，互联网是过去所出现的一个最好的东东。它包含着任何人都可以获取的有价值的信息和资源，且大部分可以免费获取。一些最著名高校的人提供了免费的高质量课程，可供任何想学习的人来学习。今天，我们都可以连入互联网真是一件好事情。</p><p>但是有些事情你一定要记住，当你连入互联网时，你的电脑就成了攻击的目标。成为病毒，木马和其它程序破坏的目标。</p><p>正因为此，推荐连入互联网的电脑都要使用反病毒和反间谍软件来保护。在有些情况下，即使使用了这些软件也不能完全保证你的安全。再添加一个安全层总是一个好主意。</p><p>当寻找添加一个额外的安全层去保护你的机器时，使用OpenDNS的安全DNS框架可能会有帮助。因特网有许多部分组成，尽力对其每一部分都进行相应保护是保证安全的最好方法。</p><p>首先，你要在你的电脑上安装反病毒和反间谍软件。由于浏览因特网时允许你的电脑查询远程DNS服务器，因此使用受保护的安全的DNS服务器将是保护你电脑安全的好方法。（译注：我们认为，其实在Ubuntu上使用反病毒和反间谍软件并不太必要，但是使用OpenDNS来拦截对恶意网址的访问是有必要的。另外，使用国外的DNS可能会比较慢，也许过一段时间，国内也会出现类似的服务。）</p><p>这是一个简明手册，告诉你如何在Ubuntu上配置OpenDNS框架以便保护你的电脑。</p><pre><code>sudo gedit /etc/dhcp/dhclient.conf
</code></pre><p>最后，在打开的文件中添加下面一行，然后保存。</p><pre><code>supersede domain-name-servers 208.67.222.222,208.67.220.220;
</code></pre><p>重启你的电脑，祝你玩的开心！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/opendns-ubuntu.png" alt=""></p><p>好好享受吧！</p><hr>`,15)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsprotect-your-computers-using-opendns-secure-dns-infrastructure/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsprotect-your-computers-using-opendns-secure-dns-infrastructure/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),u(n,{href:"https://github.com/Linux-pdz"},{default:p(()=>[...t[2]||(t[2]=[e("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const U=s(l,[["render",D]]);export{C as __pageData,U as default};
